/*
 * sid_tables_wave -- one combined-waveform table.
 * Steps:
 *   1. Select the model row and the combination column (SID_TAB_ST, _PT, _PS, _PST).
 * Returns: the table descriptor, or NULL for an out-of-range model or combination.
 */
const sid_wave_tab_t *sid_tables_wave(sid_model_t model, uint32_t combo)
{
    if ((uint32_t)model >= SID_TAB_MODELS || combo >= SID_TAB_COMBOS) {
        return NULL;
    }
    return &g_wave_tabs[(uint32_t)model][combo];
}

/*
 * sid_tables_cutoff_hz -- the FC -> cutoff curve of one model.
 * Returns: a pointer to SID_TAB_FC_ENTRIES cutoff values in Hz.
 */
const uint16_t *sid_tables_cutoff_hz(sid_model_t model)
{
    return (model == SID_MODEL_8580) ? g_cutoff_8580 : g_cutoff_6581;
}

/*
 * sid_tables_res_q10 -- 1024 / Q for one RES value.
 * Returns: the Q10 reciprocal of Q (RES is masked to 4 bits).
 */
uint32_t sid_tables_res_q10(uint32_t res)
{
    return g_res_q10[res & (SID_TAB_RES_ENTRIES - 1u)];
}
